import { useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'blockchain';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(false);
  const [generatingRoadmap, setGeneratingRoadmap] = useState(false);
  const [difficulty, setDifficulty] = useState(null);

  const fetchQuestions = async (level) => {
    setLoading(true);
    setDifficulty(level);
    try {
      const res = await fetch("http://localhost:5000/api/quiz/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ domain, difficulty: level })
      });
      setQuestions(await res.json());
    } catch (err) { console.error(err); } 
    finally { setLoading(false); }
  };

  const cleanStr = (s) => s ? s.replace(/^[a-z0-9][\s).:-]+/i, "").trim().toLowerCase() : "";

  const score = questions.reduce((acc, q, idx) => {
    return acc + (cleanStr(selected[idx]) === cleanStr(q.answer) ? 1 : 0);
  }, 0);

  const handleGenerateRoadmap = async () => {
    setGeneratingRoadmap(true);
    const savedTimeline = localStorage.getItem('timeline') || '3 months';

    try {
      const res = await fetch("http://localhost:5000/api/quiz/analyze-and-generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          domain,
          questions,
          selectedAnswers: selected,
          timeline: savedTimeline
        })
      });

      const roadmapData = await res.json();
      const finalPlan = Array.isArray(roadmapData) ? roadmapData : [];
      
      localStorage.setItem('roadmapPlan', JSON.stringify(finalPlan));
      localStorage.setItem('selectedDomain', domain);
      localStorage.setItem('quizScore', score);
      localStorage.setItem("completedDays", JSON.stringify([]));

      navigate(`/roadmap/${domain}`);
    } catch (err) {
      alert("AI failed to generate phases. Try again.");
    } finally {
      setGeneratingRoadmap(false);
    }
  };

  if (!difficulty && !loading) return (
    <div className="max-w-md mx-auto mt-20 p-10 bg-white rounded-[2rem] border text-center shadow-lg">
      <h2 className="text-2xl font-bold mb-6">Start Assessment</h2>
      <div className="flex flex-col gap-4">
        {['Easy', 'Medium', 'Hard'].map(lvl => (
          <Button key={lvl} onClick={() => fetchQuestions(lvl.toLowerCase())}>{lvl}</Button>
        ))}
      </div>
    </div>
  );

  if (loading) return <div className="p-20 text-center font-bold">AI Generating questions...</div>;

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-[2rem] p-8 border shadow-sm">
        <h2 className="text-2xl font-bold capitalize mb-8">{domain} Assessment</h2>
        <div className="space-y-8">
          {questions.map((q, idx) => (
            <div key={idx} className="p-6 rounded-2xl bg-slate-50 border">
              <p className="font-semibold mb-4">{idx + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map(opt => {
                  const isCorrect = cleanStr(opt) === cleanStr(q.answer);
                  const isSelected = selected[idx] === opt;
                  let style = "bg-white border-slate-200";
                  if (isSelected) style = "bg-blue-600 text-white";
                  if (submitted) {
                    if (isCorrect) style = "bg-green-100 border-green-500 text-green-900 ring-2 ring-green-100";
                    else if (isSelected && !isCorrect) style = "bg-red-100 border-red-500 text-red-900";
                  }
                  return (
                    <button key={opt} disabled={submitted} onClick={() => setSelected(prev => ({ ...prev, [idx]: opt }))}
                      className={`p-4 text-left border rounded-xl transition-all font-medium ${style}`}>
                      {opt}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
        <div className="mt-8 border-t pt-6">
          {!submitted ? (
            <Button onClick={() => setSubmitted(true)} disabled={Object.keys(selected).length < questions.length}>Submit</Button>
          ) : (
            <div className="flex justify-between items-center">
              <span className="text-2xl font-bold">Score: {score}/10</span>
              <Button onClick={handleGenerateRoadmap} disabled={generatingRoadmap}>
                {generatingRoadmap ? "Generating Syllabus..." : "Generate Roadmap →"}
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
